INSERT INTO public.polling_booths
  (id, internal_id, state_code, constituency_id, constituency_internal_id, booth_number,
   booth_name, polling_station_name, polling_station_address, primary_dataset_version_id, data_status)
SELECT c.id || '-B' || lpad(b.booth_number::text, 3, '0'), gen_random_uuid(),
       c.state_code, c.id, c.internal_id, b.booth_number,
       b.venue, b.venue, b.locality, b.version_id, 'OFFICIAL'
FROM published_booths b
JOIN public.constituencies c ON c.state_code = 'TS' AND c.ac_no = b.ac_no
ON CONFLICT (constituency_id, booth_number) DO NOTHING;

DO $check$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.dataset_versions v
    LEFT JOIN public.polling_booths b ON b.primary_dataset_version_id = v.id AND b.data_status = 'OFFICIAL'
    WHERE v.id IN ('eci_polling_stations_ts_ac_87_20231123', 'eci_polling_stations_ts_ac_88_20231123', 'eci_polling_stations_ts_ac_95_20231123', 'eci_polling_stations_ts_ac_86_20231123', 'eci_polling_stations_ts_ac_44_20231004', 'eci_polling_stations_ts_ac_45_20231004', 'eci_polling_stations_ts_ac_46_20231004')
    GROUP BY v.id, v.record_count
    HAVING count(b.id) <> v.record_count
  ) THEN
    RAISE EXCEPTION 'A Telangana polling-station list does not match its published count';
  END IF;
END $check$;
COMMIT;
